def get_all_questions():
    """Return all questions in the knowledge base."""
    return list(KNOWLEDGE_BASE.keys())


def get_answer(key):
    """Return the answer for an exact key."""
    return KNOWLEDGE_BASE.get(key, None)


def search_knowledge_base(query, threshold=0.3):
    """
    Simple keyword-based search through the knowledge base.
    Returns list of (question, answer, score) tuples sorted by relevance.
    """
    query = query.lower().strip()
    results = []

    for question, answer in KNOWLEDGE_BASE.items():
        q_words = set(question.split())
        query_words = set(query.split())
        common = q_words.intersection(query_words)
        if len(q_words) > 0:
            score = len(common) / max(len(q_words), len(query_words))
            if score >= threshold or query in question:
                results.append((question, answer, score))

    results.sort(key=lambda x: x[2], reverse=True)
    return results


